19. package org.apache.tinkerpop.gremlin.util;
20. 
21. import org.apache.tinkerpop.gremlin.process.traversal.GremlinTypeErrorException;
22. import org.apache.tinkerpop.gremlin.process.traversal.Path;
23. import org.apache.tinkerpop.gremlin.structure.Edge;
24. import org.apache.tinkerpop.gremlin.structure.Element;
25. import org.apache.tinkerpop.gremlin.structure.Property;
26. import org.apache.tinkerpop.gremlin.structure.Vertex;
27. import org.apache.tinkerpop.gremlin.structure.VertexProperty;
28. 
29. import java.util.*;
30. 
31. import static org.apache.tinkerpop.gremlin.util.NumberHelper.eitherAreNaN;
32. 
33. /**
34.  * This implementation extends the default one in Gremlin to avoid throwing exception in case the comparison is between different types or just with a null value.
35.  * Throwing exceptions in Java is expensive and should be avoided for such cases.
36.  *
37.  * @author Luca Garulli (l.garulli@arcadedata.com)
38.  * @author Mike Personick (http://github.com/mikepersonick)
39.  */
40. public abstract class GremlinValueComparator implements Comparator<Object> {
41. 
42.   /**
43.    * Orderability comparator allows for a total order across all types (no type error exceptions).
44.    */
45.   public static final GremlinValueComparator ORDERABILITY = new GremlinValueComparator() {
46. 
47.     /**
48.      * Compare two Gremlin value objects per the Orderability semantics.
49.      */
50.     @Override
51.     public int compare(final Object f, final Object s) {
52.       // nulls first
53.       if (f == null || s == null)
54.         return f == s ? 0 : f == null ? -1 : 1;
55. 
56.       final Type ft = Type.type(f);
57.       /*
58.        * Do a quick check to catch very common cases - class equality or both numerics. Even if these are false we
59.        * could still be dealing with the same type (e.g. different implementation of List), but let the type
60.        * lookup method handle that.
61.        */
62.       final Type st = f.getClass().equals(s.getClass()) || (f instanceof Number && s instanceof Number) ? ft : Type.type(s);
63. 
64.       return ft != st ? ft.priority() - st.priority() : comparator(ft).compare(f, s);
65.     }
66. 
67.     /**
68.      * Test for equivalence (Orderability semantics).
69.      */
70.     public boolean equals(final Object f, final Object s) {
71.       return compare(f, s) == 0;
72.     }
73.   };
74. 
75.   /**
76.    * Comparability has very similar semantics to orderability with the following exceptions:
77.    * <p>
78.    * 1. NaN is not equal to anything, including itself, and cannot be compared to anything:
79.    * equals(NaN, anything) = FALSE
80.    * compare(NaN, anything) = ERROR
81.    * 2. Unlike Orderability, Comparability is limited to a single type space:
82.    * compare(type1, type2) = ERROR
83.    * <p>
84.    * Note that because of type errors for Comparability, equals(a,b) does not necessarily produce the same result
85.    * as compare(a,b) == 0. Make sure to use equals(a,b) for P.eq/neq.
86.    */
87.   public static final GremlinValueComparator COMPARABILITY = new GremlinValueComparator() {
88. 
89.     /**
90.      * Compare two Gremlin value objects per the Comparability semantics. Throws type errors for NaN comparison
91.      * and for cross-type comparison (including nulltype).
92.      *
93.      * Use this method for P.lt/lte/gt/gte.
94.      */
95.     @Override
96.     public int compare(final Object f, final Object s) {
97.       // For Compare, NaN always produces ERROR
98.       if (eitherAreNaN(f, s))
99.         throwTypeError();
100. 
101.       // For Compare we do not cross type boundaries, including null
102.       if (!comparable(f, s))
103.         throwTypeError();
104. 
105.       // comparable(f, s) assures that type(f) == type(s)
106.       final Type type = Type.type(f);
107.       return comparator(type).compare(f, s);
108.     }
109. 
110.     /**
111.      * Test two Gremlin values for equality per the Comparability semantics. Returns false for NaN comparison
112.      * and for cross-type comparison (including nulltype).
113.      *
114.      * Use this method for P.eq/neq.
115.      */
116.     @Override
117.     public boolean equals(final Object f, final Object s) {
118.       // shortcut a long, drawn out element by element comparison
119.       if (containersOfDifferentSize(f, s))
120.         return false;
121. 
122.       // For Compare, NaN always produces ERROR
123.       if (eitherAreNaN(f, s))
124.         return false;
125. 
126.       // For Compare we do not cross type boundaries, including null
127.       if (!comparable(f, s))
128.         return false;
129. 
130.       try {
131.         // comparable(f, s) assures that type(f) == type(s)
132.         final Type type = Type.type(f);
133.         return comparator(type).compare(f, s) == 0;
134.       } catch (GremlinTypeErrorException ex) {
135.         /**
136.          * By routing through the compare(f, s) path we expose ourselves to type errors, which should be
137.          * reduced to false for equality:
138.          *
139.          * compare(NaN, anything) -> ERROR -> FALSE for equality
140.          * compare(Type1, Type2) -> ERROR -> FALSE for equality
141.          *
142.          * Can also happen for elements nested inside of collections.
143.          */
144.         return false;
145.       }
146.     }
147. 
148.     private boolean containersOfDifferentSize(final Object f, final Object s) {
149.       if (f instanceof Collection collection && s instanceof Collection collection1)
150.         if (collection.size() != (collection1.size()))
151.           return true;
152. 
153.       if (f instanceof Path path && s instanceof Path path1)
154.         if (path.size() != (path1.size()))
155.           return true;
156. 
157.       return false;
158.     }
159.   };
160. 
161.   private static <T> T throwTypeError() {
162.     throw new GremlinTypeErrorException();
163.   }
164. 
165.   /**
166.    * Boolean, Date, String, UUID.
167.    */
168.   private final Comparator<Comparable> naturalOrderComparator = Comparator.naturalOrder();
169. 
170.   /**
171.    * This comparator does not provide a stable order for numerics because of type promotion equivalence semantics.
172.    */
173.   private final Comparator<Number> numberComparator = (f, s) -> NumberHelper.compare(f, s);
174. 
175.   /**
176.    * Sort Vertex, Edge, VertexProperty by id.
177.    */
178.   private final Comparator<Element> elementComparator = Comparator.comparing(Element::id, this);
179. 
180.   /**
181.    * Sort Property first by key, then by value.
182.    */
183.   private final Comparator<Property> propertyComparator = Comparator.<Property, Object>comparing(Property::key, this).thenComparing(Property::value, this);
184. 
185.   /**
186.    * Sort List, Set, Path, and Map element-by-element in the order presented by their natural iterator.
187.    */
188.   private final Comparator<Iterable> iterableComparator = (f, s) -> {
189.     final Iterator fi = f.iterator();
190.     final Iterator si = s.iterator();
191. 
192.     while (fi.hasNext() && si.hasNext()) {
193.       final int i = this.compare(fi.next(), si.next());
194.       if (i != 0) {
195.         return i;
196.       }
197.     }
198. 
199.     return fi.hasNext() ? 1 : si.hasNext() ? -1 : 0;
200.   };
201. 
202.   /**
203.    * Compare by sorted elements.
204.    */
205.   private final Comparator<Set> setComparator = (s1, s2) -> {
206.     final List l1 = new ArrayList(s1);
207.     final List l2 = new ArrayList(s2);
208.     Collections.sort(l1, ORDERABILITY);
209.     Collections.sort(l2, ORDERABILITY);
210.     return iterableComparator.compare(l1, l2);
211.   };
212. 
213.   /**
214.    * Compare by sorted entry-set.
215.    */
216.   private final Comparator<Map> mapComparator = (m1, m2) -> {
217.     final List l1 = new ArrayList(m1.entrySet());
218.     final List l2 = new ArrayList(m2.entrySet());
219.     Collections.sort(l1, ORDERABILITY);
220.     Collections.sort(l2, ORDERABILITY);
221.     return iterableComparator.compare(l1, l2);
222.   };
223. 
224.   /**
225.    * Sort Map.Entry first by key, then by value.
226.    */
227.   private final Comparator<Map.Entry> entryComparator = Comparator.<Map.Entry, Object>comparing(Map.Entry::getKey, this)
228.       .thenComparing(Map.Entry::getValue, this);
229. 
230.   /**
231.    * Sort using either their natural order if they are Comparable or by classname then by toString() if they are
232.    * not naturally Comparable. Also handles the special case: f.equals(s) -> 0 even for objects without a natural
233.    * comparator.
234.    */
235.   private final Comparator<Object> unknownTypeComparator = (f, s) -> naturallyComparable(f, s) ?
236.       naturallyCompare(f, s) :
237.       Comparator.comparing(o -> o.getClass().getName()).thenComparing(Object::toString).compare(f, s);
238. 
239.   /**
240.    * Two nulls. Always 0.
241.    */
242.   private final Comparator<Object> nulltypeComparator = (f, s) -> 0;
243. 
244.   /**
245.    * The typespace. The ordinal of the type indicates its position in cross-type ordering.
246.    */
247.   public enum Type {
248.     Nulltype, Boolean(Boolean.class), Number(Number.class), Date(Date.class), String(String.class), UUID(UUID.class), Vertex(Vertex.class), Edge(
249.         Edge.class), VertexProperty(VertexProperty.class), Property(Property.class), Path(Path.class), Set(Set.class), List(List.class), Map(
250.         Map.class), MapEntry(Map.Entry.class), Unknown(Object.class);
251. 
252.     /**
253.      * Lookup by instanceof semantics (not class equality). Current implementation will return first enum value
254.      * that matches the object's type.
255.      */
256.     public static Type type(final Object o) {
257.       if (o == null)
258.         return Nulltype;
259. 
260.       final Type[] types = Type.values();
261.       for (int i = 1; i < types.length; i++) {
262.         if (types[i].type.isInstance(o)) {
263.           return types[i];
264.         }
265.       }
266.       return Unknown;
267.     }
268. 
269.     Type() {
270.       this.type = null;
271.     }
272. 
273.     Type(final Class type) {
274.       this.type = type;
275.     }
276. 
277.     private final Class type;
278. 
279.     public int priority() {
280.       return ordinal();
281.     }
282.   }
283. 
284.   /**
285.    * Compare the two objects using their natural comparator. Also handles the special case: f.equals(s) -> 0 even
286.    * for objects without a natural comparator.
287.    */
288.   private static int naturallyCompare(final Object f, final Object s) {
289.     if (f instanceof Comparable comparable && s instanceof Comparable)
290.       return comparable.compareTo(s);
291.     return f.equals(s) ? 0 : throwTypeError();
292.   }
293. 
294.   /**
295.    * Return true if the two objects in the UNKNOWN type space are equal or comparable via their own natural Comparator.
296.    */
297.   private static boolean naturallyComparable(final Object f, final Object s) {
298.     return (f instanceof Comparable && s instanceof Comparable && (f.getClass().isInstance(s) || s.getClass().isInstance(f))) || f.equals(s);
299.   }
300. 
301.   /**
302.    * Return true if the two objects are of the same comparison type (although they may not be the exact same Class)
303.    */
304.   private static boolean comparable(final Object f, final Object s) {
305.     if (f == null || s == null)
306.       return f == s; // true iff both in the null space
307. 
308.     final Type ft = Type.type(f);
309.     final Type st = Type.type(s);
310. 
311.     // Check for same type. If they're both the unknown type then return true iff they are naturally Comparable
312.     return ft == Type.Unknown && st == Type.Unknown ? naturallyComparable(f, s) : ft == st;
313.   }
314. 
315.   private final Map<Type, Comparator> comparators = new EnumMap<Type, Comparator>(Type.class) {{
316.     put(Type.Nulltype, nulltypeComparator);
317.     put(Type.Boolean, naturalOrderComparator);
318.     put(Type.Number, numberComparator);
319.     put(Type.Date, naturalOrderComparator);
320.     put(Type.String, naturalOrderComparator);
321.     put(Type.UUID, naturalOrderComparator);
322.     put(Type.Vertex, elementComparator);
323.     put(Type.Edge, elementComparator);
324.     put(Type.VertexProperty, elementComparator);
325.     put(Type.Property, propertyComparator);
326.     put(Type.Path, iterableComparator);
327.     put(Type.Set, setComparator);
328.     put(Type.List, iterableComparator);
329.     put(Type.Map, mapComparator);
330.     put(Type.MapEntry, entryComparator);
331.     put(Type.Unknown, unknownTypeComparator);
332.   }};
333. 
334.   private GremlinValueComparator() {
335.   }
336. 
337.   protected Comparator comparator(final Type type) {
338.     return comparators.get(type);
339.   }
340. 
341.   /**
342.    * Compare(a,b) is defined differently for Comparablity vs. Orderability.
343.    */
344.   public abstract int compare(final Object f, final Object s);
345. 
346.   /**
347.    * Equals(a,b) is defined differently for Comparablity (equality) vs. Orderability (equivalence).
348.    */
349.   public abstract boolean equals(final Object f, final Object s);
350. 
351. }
352.

