     *
     * <pre>
     *     a = 4, b = 2 -> 4
     *     a = null, b = 1 -> 1
     *     a = 1, b = null -> 1
     *     a = null, b = null -> null
     *     a = NaN, b = 1 -> 1
     *     a = 1, b = NaN -> 1
